onClick:
{{
  (() => {
    JSutils.resetInactivityTimer();
    const formData = {
      vet001_id:          (InputID.text),
      vet001_nome:        (InputNome.text).trim().toUpperCase(),
      vet001_crmv:        parseInt(InputCRMV.text) || 0,
      vet001_endereco:    (InputEndereco.text).trim().toUpperCase(),
      vet001_bairro:      (InputBairro.text).trim().toUpperCase(),
      vet001_numero:      (InputNumero.text).trim().toUpperCase(),
      vet001_complemento: (InputComplemento.text).trim().toUpperCase(),
      vet001_cidade:      (InputCidade.text).trim().toUpperCase(),
      vet001_email:       (InputEmail.text).trim().toLowerCase(),
      vet001_telefone:    (InputTelefone.text).trim().toString().replace(/\D/g, ""),
      vet001_celular:     (InputCelular.text).trim().toString().replace(/\D/g, ""),
      vet001_uf:          (SelectUF.selectedOptionValue).trim().toUpperCase(),
      vet001_comissao:    "0",
      vet001_cep:         (InputCep.text).trim().toString().replace(/\D/g, ""),
      vet001_clinica:     SelectClinica.selectedOptionValue || null
    };

    if (appsmith.store.modalContexto?.acaoTipo === "ADICIONAR") {
      return JSconfirmation.showModal({
        action: "Insert",
        message: "Deseja salvar este novo registro?",
        icon: "plus",
        color: "green",
        row: formData
      });
    } else {
      return JSconfirmation.showModal({
        action: "Update",
        message: "Deseja salvar as alterações deste registro?",
        icon: "edit",
        color: "orange",
        row: formData
      });
    }
  })()
}}
